        "text": "__osrt1__:{\"version\":1,\"root\":{\"type\":\"root\",\"children\":[{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"Do not attempt to interfere with the operation or security of cashpath.org, introduce malicious code, circumvent technical protections, access systems without authorization, automate abusive requests, misuse another person's information, or use CashPath to facilitate fraud or other unlawful conduct.\"}]},{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"CashPath may restrict access when reasonably necessary to protect the website, visitors, integrations, or third parties.\"}]}]}}",
