        "text": "__osrt1__:{\"version\":1,\"root\":{\"type\":\"root\",\"children\":[{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"CashPath publishes information intended to help visitors understand subjects such as personal loan requests, APR, fees, repayment terms, responsible borrowing, privacy, and online scam awareness.\"}]},{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"This material is general educational information.\"}]},{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"It is not individualized financial, investment, legal, tax, credit, or accounting advice.\"}]}]}}",
