        "text": "__osrt1__:{\"version\":1,\"root\":{\"type\":\"root\",\"children\":[{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"CashPath may link to or interact with third-party technology, referral networks, providers, government educational resources, or other external websites.\"}]},{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"CashPath does not control every third-party website or service and is not responsible for changing third-party content, independent privacy practices, provider decisions, or separate agreements.\"}]},{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"An external link is not necessarily an endorsement.\"}]}]}}",
