        "text": "__osrt1__:{\"version\":1,\"root\":{\"type\":\"root\",\"children\":[{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"Before accepting a financial obligation, review the cost and repayment requirements and decide whether they are manageable for your circumstances.\"}]},{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"CashPath cannot make that decision for you.\"}]},{\"type\":\"p\",\"children\":[{\"type\":\"text\",\"text\":\"For general educational guidance, see \"},{\"type\":\"a\",\"href\":\"/p/rates-fees\",\"children\":[{\"type\":\"text\",\"text\":\"Rates & Fees\"}]},{\"type\":\"text\",\"text\":\" and \"},{\"type\":\"a\",\"href\":\"/p/responsible-lending\",\"children\":[{\"type\":\"text\",\"text\":\"Responsible Borrowing\"}]},{\"type\":\"text\",\"text\":\".\"}]}]}}",
